use std::io::{self, Read};

trait Shape {
    fn name(&self) -> &str;
    fn corners(&self) -> u32;
    fn double_area(&self) -> u128;
}

struct Gen {
    name: String,
    corners: u32,
    d: u128,
}

impl Shape for Gen {
    fn name(&self) -> &str {
        &self.name
    }
    fn corners(&self) -> u32 {
        self.corners
    }
    fn double_area(&self) -> u128 {
        self.d
    }
}

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut shapes: Vec<Box<dyn Shape>> = Vec::new();
    for line in s.lines() {
        let w: Vec<&str> = line.split_whitespace().collect();
        if w.is_empty() {
            continue;
        }
        let n: Vec<u128> = w[1..].iter().filter_map(|x| x.parse().ok()).collect();
        let (c, d) = match w[0] {
            "square" => (4, 2 * n[0] * n[0]),
            "rect" => (4, 2 * n[0] * n[1]),
            "rtri" => (3, n[0] * n[1]),
            "trap" => (4, (n[0] + n[1]) * n[2]),
            _ => continue,
        };
        shapes.push(Box::new(Gen { name: w[0].to_string(), corners: c, d }));
    }
    let mut total: u128 = 0;
    let mut best: Option<usize> = None;
    for (i, sh) in shapes.iter().enumerate() {
        println!("{} corners={} area2={}", sh.name(), sh.corners(), sh.double_area());
        total += sh.double_area();
        if best.map_or(true, |b| sh.double_area() > shapes[b].double_area()) {
            best = Some(i);
        }
    }
    println!("total area2={}", total);
    match best {
        Some(b) => println!("largest={} area2={}", shapes[b].name(), shapes[b].double_area()),
        None => println!("largest=none"),
    }
}

